    def search(self, query: str):
        """검색어(한글, 한자)가 포함된 모든 사전 데이터를 반환합니다."""
        if not query or query.strip() == "":
            return self.db
            
        q = query.strip()
        results = []
        for item in self.db:
            if (q in item["term"]) or (q in item["hanja"]) or (q in item["meaning"]) or (q in item["category"]):
                results.append(item)
        return results